(() => {
'use strict';
const q=s=>document.querySelector(s),labels={new:'Нова',contacted:'Зв’язалися',confirmed:'Підтверджено',cancelled:'Скасовано'};
const messages={not_authorized:'Увійдіть до кабінету.',invalid_login:'Не вдалося увійти. Перевірте email, пароль та доступ до кабінету.',too_many_requests:'Забагато спроб. Зачекайте кілька хвилин.',invalid_date:'Перевірте майбутню дату та час прийому за Києвом.',slot_taken:'Цей час уже зайнятий підтвердженим прийомом. Узгодьте інший час.',request_changed:'Заявку вже змінив інший адміністратор. Оновіть список.',service_unavailable:'Сервіс тимчасово недоступний або ще не підключений.',doctor_unavailable:'Лікар недоступний для цього розділу.'};
let offset=0,session=false;
const el=(tag,text,className)=>{const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(className)node.className=className;return node;};
function notice(text){q('#notice').textContent=text||'';q('#notice').hidden=!text;}
function signedIn(value){session=value;q('#login-panel').hidden=value;q('#dashboard').hidden=!value;q('#logout').hidden=!value;if(!value){q('#requests').replaceChildren();q('#slots').replaceChildren();q('#password').value='';}}
async function api(path,options={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);try{const response=await fetch(path,{...options,credentials:'same-origin',signal:controller.signal,headers:{'Content-Type':'application/json',Accept:'application/json',...options.headers}});const data=await response.json();if(!response.ok||!data.ok){if(response.status===401){signedIn(false);}const error=new Error(data.code||'service_unavailable');error.code=data.code||'service_unavailable';throw error;}return data;}finally{clearTimeout(timer);}}
function error(e){notice(messages[e.code]||messages.service_unavailable);}
const time=value=>new Intl.DateTimeFormat('uk-UA',{timeZone:'Europe/Kyiv',dateStyle:'medium',timeStyle:'short'}).format(new Date(value));
const inputTime=value=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Kyiv',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(value)).replace(' ','T');
function requestCard(row){const card=el('article',undefined,'request');card.append(el('span',labels[row.status],'badge'),el('h2',row.doctor_name),el('p',row.specialty),el('p',row.patient_name,'patient'));const phone=el('a',row.phone);if(/^\+380\d{9}$/.test(row.phone))phone.href='tel:'+row.phone;card.append(phone,el('p','Бажаний час: '+time(row.preferred_start)),el('p','Отримано: '+time(row.created_at),'muted'));if(row.confirmed_start)card.append(el('p','Узгоджено: '+time(row.confirmed_start)));
 const form=el('form',undefined,'edit'),statusLabel=el('label','Результат'),select=el('select');select.setAttribute('aria-label','Результат заявки');for(const [value,label]of Object.entries(labels)){const option=el('option',label);option.value=value;select.append(option);}select.value=row.status;statusLabel.append(select);const dateLabel=el('label','Узгоджений час за Києвом'),date=el('input');date.type='datetime-local';date.value=inputTime(row.confirmed_start||row.preferred_start);dateLabel.append(date);const save=el('button',row.status==='new'?'Підтвердити цей час':'Зберегти');save.className='primary';form.append(statusLabel,dateLabel,save);card.append(form);
 if(row.status==='new'){select.value='confirmed';}
 select.addEventListener('change',()=>{date.required=select.value==='confirmed';dateLabel.hidden=select.value!=='confirmed';save.textContent=select.value==='confirmed'?'Підтвердити цей час':'Зберегти';});date.required=select.value==='confirmed';dateLabel.hidden=select.value!=='confirmed';
 form.addEventListener('submit',async event=>{event.preventDefault();save.disabled=true;notice('');try{await api('/api/admin/requests',{method:'PATCH',body:JSON.stringify({id:row.id,version:row.version,status:select.value,confirmedTime:date.value})});notice('Зміни збережено. Пацієнта потрібно повідомити про узгоджений прийом.');await loadRequests();}catch(e){error(e);}finally{save.disabled=false;}});return card;}
async function loadRequests(){q('#refresh').disabled=true;try{const data=await api('/api/admin/requests?status='+q('#status-filter').value+'&offset='+offset);q('#requests').replaceChildren(...(data.requests.length?data.requests.map(requestCard):[el('p','У цьому списку заявок немає.','muted')]));q('#previous').disabled=offset===0;q('#next').disabled=!data.hasMore;}finally{q('#refresh').disabled=false;}}
async function loadDoctors(){const data=await api('/api/booking/doctors');q('#schedule-doctor').replaceChildren(...data.doctors.filter(d=>d.mode==='callback').map(d=>{const option=el('option',d.name+' — '+d.specialty);option.value=d.siteId;return option;}));}
async function loadSlots(){const id=q('#schedule-doctor').value,date=q('#schedule-date').value;if(!id||!date)return;const data=await api('/api/admin/slots?doctorId='+encodeURIComponent(id)+'&start='+date);q('#slots').replaceChildren(...data.slots.filter(s=>s.active).map(slot=>{const line=el('div',undefined,'slot'),button=el('button','Закрити вікно');line.append(el('span',time(slot.starts_at)+' — '+new Intl.DateTimeFormat('uk-UA',{timeZone:'Europe/Kyiv',hour:'2-digit',minute:'2-digit'}).format(new Date(slot.ends_at))),button);button.addEventListener('click',async()=>{button.disabled=true;try{await api('/api/admin/slots',{method:'PATCH',body:JSON.stringify({id:slot.id})});await loadSlots();}catch(e){error(e);}finally{button.disabled=false;}});return line;}));}
q('#login-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;notice('');try{await api('/api/admin/session',{method:'POST',body:JSON.stringify({email:q('#email').value,password:q('#password').value})});q('#password').value='';signedIn(true);await Promise.all([loadRequests(),loadDoctors()]);}catch(e){error(e);}finally{button.disabled=false;}});
q('#logout').addEventListener('click',async()=>{try{await api('/api/admin/session',{method:'DELETE'});}catch{/* Clear displayed data on every sign-out attempt. */}signedIn(false);notice('');});
q('#refresh').addEventListener('click',()=>loadRequests().catch(error));q('#status-filter').addEventListener('change',()=>{offset=0;loadRequests().catch(error);});q('#previous').addEventListener('click',()=>{offset=Math.max(0,offset-50);loadRequests().catch(error);});q('#next').addEventListener('click',()=>{offset+=50;loadRequests().catch(error);});
function tab(schedule){q('#requests-panel').hidden=schedule;q('#schedule-panel').hidden=!schedule;q('#requests-tab').setAttribute('aria-pressed',String(!schedule));q('#schedule-tab').setAttribute('aria-pressed',String(schedule));}
q('#requests-tab').addEventListener('click',()=>tab(false));q('#schedule-tab').addEventListener('click',()=>{tab(true);loadSlots().catch(error);});q('#load-slots').addEventListener('click',()=>loadSlots().catch(error));
for(let hour=0;hour<=24;hour++){if(hour<24){const option=el('option',String(hour).padStart(2,'0')+':00');option.value=hour;q('#from-hour').append(option);}if(hour>0){const option=el('option',String(hour).padStart(2,'0')+':00');option.value=hour;q('#to-hour').append(option);}}q('#from-hour').value='9';q('#to-hour').value='13';q('#schedule-date').value=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Kyiv'}).format(new Date());q('#schedule-date').min=q('#schedule-date').value;
q('#schedule-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;notice('');try{await api('/api/admin/slots',{method:'POST',body:JSON.stringify({doctorId:q('#schedule-doctor').value,date:q('#schedule-date').value,fromHour:Number(q('#from-hour').value),toHour:Number(q('#to-hour').value)})});notice('Години відкрито для заявок на сайті.');await loadSlots();}catch(e){error(e);}finally{button.disabled=false;}});
async function checkSession(){try{await api('/api/admin/session');signedIn(true);await Promise.all([loadRequests(),loadDoctors()]);}catch(e){signedIn(false);if(e.code!=='not_authorized')error(e);}}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&session)checkSession();});checkSession();
})();
